// The app's own commands, one entry per command registered in
// `invoke_handler` (src/lib.rs). With an app manifest, Tauri checks every
// app command against the capabilities like a plugin command, instead of
// letting any local-origin webview call it (#449). Each name here gets an
// `allow-<command>` permission under `permissions/autogenerated/`, and only
// `capabilities/default.json` (the main window) grants them.
//
// `sidecar/test/app-command-acl.test.mjs` fails when this list, the
// `invoke_handler` list and the main capability drift apart.
const APP_COMMANDS: &[&str] = &[
    "html_preview",
    "spawn_pty",
    "write_pty",
    "resize_pty",
    "kill_pty",
    "kill_all_ptys",
    "home_dir",
    "load_config",
    "save_config",
    "account_env_text",
    "seal_account_env",
    "save_account_avatar",
    "account_avatar",
    "delete_account_avatar",
    "save_sessions",
    "load_sessions",
    "room_port",
    "room_participants",
    "topic_status",
    "update_topic_work",
    "room_join",
    "room_post",
    "room_current_topic",
    "room_new_topic",
    "room_select_topic",
    "room_delete_topic",
    "room_topics",
    "room_topic_log",
    "room_rename_topic",
    "room_forget_session",
    "room_attach_path",
    "room_attach_bytes",
    "room_attachments_dir",
    "room_attachment",
    "codex_remote_control",
    "seated_accounts",
    "parse_launch_options",
    "launch_field_report",
    "preview_launch_args",
    "start_session",
    "mcp_servers",
    "save_mcp_server",
    "create_mcp_server",
    "delete_mcp_server",
    "restart_mcp_server",
    "open_mcp_servers_file",
    "open_character_file",
    "setup_codex_output_style",
    "save_character_file",
    "character_file_wearers",
    "permission_answer",
    "permission_requests",
    "open_post_url",
    "open_post_path",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
